const smoke=(c,x,y,col)=>{for(let i=0;i<3;i++){const px=x+i*1.8,py=y-i*3.4,r=1.3+i*.7;c.fillStyle="#4a3d3f";c.beginPath();c.arc(px,py,r+.6,0,7);c.fill();c.fillStyle=col||"#c9b9b3";c.beginPath();c.arc(px,py,r,0,7);c.fill()}};
